### 语法速查
```c
int max_value(int a[][4], int m, int n);   /* 列数 4 必须写，行数可省 */
int max_value(int a[2][4], int m, int n);  /* 等价：第一维的数字被忽略 */

int max_value(int a[][4], int m, int n) {
    int i, j, mx = a[0][0];
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            if (a[i][j] > mx) mx = a[i][j];
    return mx;
}

max_value(a, 2, 4);        /* 实参直接写二维数组名 */
```

### 为什么列数不能省
地址换算公式是「首地址 + (i × 列数 + j) × 元素大小」，列数是公式的一部分，编译期必须知道；行数只是循环上限，可以运行时传入。

### 教材常见考法
「函数 f 的形参 a 是 10×10 的二维数组，实参数组是 5×5，n 传 5」——这时形参声明的 10 与实参的 5 **不一致**，元素定位会错位，是典型的错误代码；正确做法是让形参列数与实参一致，或把列数也作为参数传入。

### 常见任务
求矩阵最大值及其位置、按行求和、转置、输出上三角或下三角，都是在这个形参骨架上改循环体。

examples.code:
#include <stdio.h>

int max_value(int a[][4], int m, int n) {
    int i, j, mx = a[0][0];
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            if (a[i][j] > mx) mx = a[i][j];
    return mx;
}

int main(void) {
    int a[2][4] = {{1, 8, 3, 4}, {5, 6, 7, 2}};
    printf("%d\n", max_value(a, 2, 4));
    return 0;
}

#include <stdio.h>

int g = 10;

void f(int a) {
    int b = 5;
    g += a + b;
    printf("%d %d %d\n", a, b, g);
}

int main(void) {
    f(1);
    printf("%d\n", g);
    return 0;
}

#include <stdio.h>

int x = 1;

void f(void) {
    int x = 2;
    printf("%d ", x);
    {
        int x = 3;
        printf("%d ", x);
    }
    printf("%d ", x);
}

int main(void) {
    f();
    printf("%d\n", x);
    return 0;
}

#include <stdio.h>

void f(void) {
    auto int n = 0;    /* auto 可省略，含义不变 */
    n++;
    printf("%d ", n);
}

int main(void) {
    f(); f(); f();
    printf("\n");
    return 0;
}

#include <stdio.h>

int count_auto(void) { int c = 0; return ++c; }

int count_static(void) { static int c = 0; return ++c; }

int main(void) {
    int i;
    for (i = 0; i < 3; i++) printf("%d ", count_auto());
    printf("| ");
    for (i = 0; i < 3; i++) printf("%d ", count_static());
    printf("\n");
    return 0;
}

#include <stdio.h>

static int local_to_file = 1;   /* 只在本文件可见 */
int shared = 2;                 /* 可被其他文件 extern 引用 */

void f(void) {
    local_to_file += 10;
    shared += 20;
}

int main(void) {
    f();
    printf("%d %d\n", local_to_file, shared);
    return 0;
}

#include <stdio.h>

int g;                /* 普通全局：未初始化自动为 0 */
static int s;         /* 静态全局：同样自动为 0 */

void f(void) {
    int a;            /* auto：值是垃圾，绝不打印它 */
    static int b;     /* 静态局部：自动为 0 */
    b++;
    printf("%d %d\n", g, b);
    (void)a;          /* 只是让编译器知道 a 被有意忽略 */
    s++;
}

int main(void) {
    f();
    f();
    printf("%d\n", s);
    return 0;
}

#include <stdio.h>

int helper(int x) { return x * 2; }   /* 实现细节，本应写成 static */
static int helper2(int x) { return helper(x) + 1; }

int api(int x) { return helper2(x); }  /* 对外接口 */

int main(void) {
    printf("%d\n", api(5));
    return 0;
}

#include <stdio.h>
#include <math.h>

int main(void) {
    printf("%.2f %.2f %.2f\n", sqrt(2.0), pow(2.0, 10), fabs(-3.5));
    printf("%d %d\n", (int)ceil(2.1), (int)floor(2.9));
    return 0;
}

